  "Браузер может скрывать модель и точную версию ОС. Задайте своё имя, чтобы различать одинаковые устройства. IP может совпадать у устройств в одной сети или меняться при VPN.": "Your browser may hide the model and exact OS version. Set a name to distinguish similar devices. Devices on the same network may share an IP, and a VPN may change it.",
  "Участники проектов": "Project members",
  "Ссылки «Поделиться»": "Shared links",
  "Отозвать всё": "Revoke all",
