  "Открыть запись": "Open record",
  "Копировать ссылку: {0}": "Copy link: {0}",
  "Ссылка скопирована": "Link copied",
  "Ссылка «Поделиться»": "Shared link",
  "Отозвать все доступы и ссылки?": "Revoke all access and shared links?",
  "Участники потеряют доступ к проектам ваших компьютеров, все ссылки «Поделиться» и ссылки на файлы отключатся. Вернуть их можно, только выдав доступ и создав ссылки заново.": "Members will lose access to projects on your computers, and all shared links and file links will stop working. To restore access, grant it and create links again.",
  "Все доступы и ссылки отозваны": "All access and shared links revoked",
  "Проекты ваших компьютеров никому не открыты.": "Projects on your computers are not shared with anyone.",
  "Ссылок нет.": "No links.",
  "Ссылки на файлы": "File links",
  "Действующих ссылок на файлы: {0}.": "Active file links: {0}.",
  "Ссылок на файлы нет.": "No file links.",
  "Доступы и ссылки": "Access and links",
  "Кому открыты проекты ваших компьютеров и какие чаты и записи доступны по ссылке. Доступ привязан к имени папки: удаление или переименование папки его не снимает — отзовите его здесь.": "People with access to projects on your computers and chats and records available by link. Access is tied to the folder name: deleting or renaming the folder does not revoke it. Revoke it here.",
  "Аварийный выход": "Emergency sign-out",
  "Введите пароль учётки": "Enter your account password",
  "Выйти везде": "Sign out everywhere",
  "Выйти на всех устройствах?": "Sign out on all devices?",
  "Все сессии, включая эту, завершатся; ссылки «Поделиться», ссылки на файлы, почтовые ссылки и коды отключатся; участники потеряют доступ к проектам ваших компьютеров; push и ntfy придётся включить заново. После выхода смените пароль: со старым можно войти снова.": "All sessions, including this one, will end. Shared links, file links, email links and codes, and project access will be revoked. Push and ntfy notifications will need to be enabled again. Change your password afterwards: the old one can still sign in.",
  " Компьютеры будут отвязаны — мосты войдут снова только с паролем.": " Computers will be unlinked. Bridges will need your password to sign in again.",
  "Если телефон или пароль могли попасть в чужие руки: завершает все сессии, отключает ссылки «Поделиться», ссылки на файлы, почтовые ссылки и коды, доступ участников к проектам, push и ntfy. История и настройки остаются. Затем смените пароль.": "If your phone or password may have been compromised, end all sessions and revoke shared links, file links, email links and codes, project access, push and ntfy. History and settings are kept. Then change your password.",
  "Пароль учётки": "Account password",
  "Отозвать и ключи компьютеров (мосты)": "Also revoke computer keys (bridges)",
  "Открыть «Защиту»": "Open Security",
  "Пароль сменил администратор": "Password changed by administrator",
  "Понятно": "Got it",
  "Пароль вашей учётки сбросил администратор {0}. Если вы об этом не просили, ": "Your account password was reset by administrator {0}. If you did not request this, ",
  "кто-то мог войти в учётку.": "someone may have accessed your account.",
  "Проверьте «Сессии» и сделайте «Аварийный выход»: он завершит все сессии, отключит ссылки «Поделиться», доступ участников к проектам, push и ntfy.": "Check Sessions and use Emergency sign-out to end all sessions and revoke shared links, project access, push and ntfy.",
  "Показать ещё": "Show more",
  "×{0}, с {1}": "×{0}, since {1}",
  "это устройство": "this device",
  "Событий пока нет.": "No events yet.",
  "Журнал безопасности": "Security log",
  "Входы и неудачные попытки (и коды из письма), отпирания и настройка блокировки, PIN и ключи, завершённые сессии, ссылки «Поделиться» и ссылки на файлы за полгода; повторы неудач с одного адреса — одной строкой со счётчиком. «Удалить всю историю» его не стирает; он входит в выгрузку истории.": "Sign-ins and failed attempts (including email codes), unlocks and app lock settings, PINs, passkeys, ended sessions, shared links and file links over the last six months. Repeated failures from the same address are grouped with a counter. Clearing history does not erase this log; it is included in history exports.",
  "Логин": "Login",
  "Имя": "Name",
