  "Отправить снова": "Resend",
  "Приглашения": "Invitations",
  "Ссылка одноразовая, действует 48 часов. Получатель сам выбирает логин и пароль.": "The link can be used once within 48 hours. The recipient chooses their own login and password.",
  "Показать ссылку": "Show link",
  "Показать ссылку приглашения?": "Show invitation link?",
  "Новая ссылка для {0} заменит прежнюю и будет действовать 48 часов. Почта учётки будет считаться подтверждённой вами, а не письмом.": "A new link for {0} replaces the previous one and is valid for 48 hours. The account email will count as confirmed by you, not by a letter.",
  "Передайте ссылку только адресату. После закрытия окна её не показать — только выпустить новую.": "Give the link only to the recipient. Once this window is closed, it cannot be shown again; you can only issue a new one.",
  "Ссылка приглашения": "Invitation link",
  "Создать и показать ссылку": "Create and show link",
  "Почта не настроена: письма не будет. После вашего пароля Студия создаст приглашение и покажет ссылку — передайте её адресату сами.": "Email is not set up, so no letter will be sent. After you enter your password, Studio creates the invitation and shows the link. Pass it to the recipient yourself.",
  "Письмо не ушло. Можно создать ссылку и передать её адресату самому: введите свой пароль.": "The letter was not sent. You can create a link and pass it to the recipient yourself: enter your password.",
  "IP:порт или имя:порт, например 10.0.0.5:4000 или api.openai.com:443": "IP:port or hostname:port, e.g. 10.0.0.5:4000 or api.openai.com:443",
  "Удалить {0}": "Delete {0}",
  "Список пуст: через сервер не идёт ни одно подключение": "The list is empty: no connections use the server",
  "Сохранено": "Saved",
  "Есть несохранённые изменения — нажмите «Сохранить»": "There are unsaved changes. Click Save",
  "Пароль «{0}» сменён, все его сессии закрыты": "Password for “{0}” changed; all their sessions are closed",
  "Разрешённые внутренние адреса": "Allowed internal addresses",
  "Комментарий к адресу {0}": "Comment for address {0}",
  "Список адресов изменился. Откройте раздел заново": "The address list changed. Reopen this section",
  "Сколько раз за один ответ модель может вызвать инструменты (интернет, MCP, вопросы), прежде чем ответить по найденному. Повторный вызов с теми же аргументами не исполняется.": "How many times the model can call tools (internet, MCP, questions) in one answer before it answers from what it found. A repeated call with the same arguments is not run.",
  "Кругов инструментов на ответ (1–30)": "Tool rounds per answer (1–30)",
  "Подключения к этим адресам студия зовёт сама, их токен браузеру не отдаётся. Запись — IP и порт (10.0.0.5:4000, [::1]:8080) или имя и порт (api.openai.com:443). Имя — только для https: студия при каждом запросе проверяет, что имя ведёт в интернет, а не во внутреннюю сеть.": "Studio connects to these addresses itself and does not expose their tokens to the browser. Enter an IP and port (10.0.0.5:4000, [::1]:8080) or a hostname and port (api.openai.com:443). Hostnames require HTTPS. Studio checks on every request that the name resolves to the internet, not an internal network.",
