  "Ссылку больше не открыть: ключ данных студии сменили. Создайте новую или отключите эту.": "This link can no longer be opened because Studio's data key changed. Create a new link or disable this one.",
  "Ссылка для чтения": "Read-only link",
  "Создать ссылку": "Create link",
  "Отключить ссылку": "Disable link",
  "PIN доступа · 4 цифры": "Access PIN · 4 digits",
  "Срок ссылки": "Link expiration",
  "Показать рассуждение модели": "Show model reasoning",
  "Получатель увидит снимок всей переписки и вложения, только для чтения. При каждом открытии нужен PIN этого чата. Передайте его отдельно от ссылки.": "The recipient will see a read-only snapshot of the entire conversation and attachments. The chat PIN is required every time. Send it separately from the link.",
  "Новая ссылка отключит прежнюю. «Обновить снимок» заменит содержимое под тем же адресом и PIN, само оно не обновляется. Снимок хранится зашифрованным и удаляется по истечении срока; после 50 неверных PIN ссылка отключится сама.": "A new link disables the previous one. Update snapshot replaces the content under the same address and PIN; it does not update by itself. The snapshot is encrypted and deleted when it expires; 50 incorrect PIN attempts disable the link automatically.",
  "Создать новую ссылку": "Create new link",
  "Обновить снимок": "Update snapshot",
  "Поделиться": "Share",
  "Снимок обновлён": "Snapshot updated",
  "Поделиться…": "Share…",
  "Не удалось открыть окно «Поделиться»": "Could not open the Share window",
  "Ссылка на запись": "Record link",
  "Поделиться расшифровкой": "Share transcript",
  "Поделиться переводом": "Share translation",
  "Поделиться сканом": "Share scan",
  "Поделиться картинкой": "Share picture",
  "Поделиться роликом": "Share video",
  "Приложить запись разговора": "Attach the conversation recording",
  "Приложить исходный файл": "Attach the source file",
  "Получатель увидит текст расшифровки с собеседниками и временем, только для чтения. При каждом открытии нужен PIN. Передайте его отдельно от ссылки.": "The recipient will see a read-only transcript with speakers and times. The PIN is required every time. Send it separately from the link.",
  "Получатель увидит исходный текст и перевод, только для чтения. При каждом открытии нужен PIN. Передайте его отдельно от ссылки.": "The recipient will see a read-only source text and translation. The PIN is required every time. Send it separately from the link.",
  "Получатель увидит распознанный текст страниц, только для чтения. При каждом открытии нужен PIN. Передайте его отдельно от ссылки.": "The recipient will see the read-only recognized text of the pages. The PIN is required every time. Send it separately from the link.",
  "Получатель увидит картинку и её промпт, только для чтения. При каждом открытии нужен PIN. Передайте его отдельно от ссылки.": "The recipient will see the picture and its prompt, read only. The PIN is required every time. Send it separately from the link.",
  "Получатель увидит ролик и его промпт, только для чтения. При каждом открытии нужен PIN. Передайте его отдельно от ссылки.": "The recipient will see the video and its prompt, read only. The PIN is required every time. Send it separately from the link.",
  "Скопируйте выделенную ссылку": "Copy the selected link",
  "скан ещё распознаётся — отправлю, когда будет готов": "scan recognition in progress; will send when ready",
  "Запись уйдёт во внешний сервис — выберите модель": "This recording will be sent to an external service. Choose a model",
  "Задайте ключ Exa в Настройках → Ввод и интернет → Интернет": "Set your Exa key in Settings → Input and internet → Internet",
  "В этом диалоге сработал защищённый источник — «Интернет» здесь недоступен": "A protected source was used in this conversation, so Internet is unavailable here",
  "Администратор разрешил «Интернет» только в диалогах через Cleaner": "The administrator allows Internet only in conversations through Cleaner",
  "В этом диалоге сработал защищённый источник — им нельзя поделиться и его нельзя скачать": "A protected source was used in this conversation, so it cannot be shared or downloaded",
  "Защищённый источник": "Protected source",
  "В диалоге по умолчанию": "On by default in conversations",
  "Без отметки сервер не предлагается в новых диалогах: пользователь включает его в окне MCP диалога.": "When unchecked, the server is not offered in new conversations: users turn it on in the conversation's MCP window.",
  "В диалог — вручную": "Turned on in conversations manually",
  "включается в диалоге вручную": "turned on in this conversation manually",
  "После первого успешного вызова инструмента этого сервера в диалоге выключаются «Интернет» и веб-инструменты, а вызовы со ссылками в аргументах отклоняются.": "After the first successful call to a tool of this server, Internet and web tools are turned off in the conversation, and calls with links in their arguments are refused.",
