  "Cleaner: владелец служебного ключа больше не администратор Cleaner — верните ему роль или выпустите служебный ключ у администратора Cleaner": "Cleaner: the owner of the service key is no longer a Cleaner administrator. Restore the role or issue the service key under a Cleaner administrator",
  "веб-инструментов хода больше, чем принимает Cleaner (128) — выключите часть MCP-серверов с пометкой «интернет»": "This turn has more web tools than Cleaner accepts (128). Turn off some MCP servers marked “internet”",
