  "Cleaner ответил, но не все проверки пройдены": "Cleaner answered, but not all checks passed",
  "Шлюз Cleaner для внешних моделей: текст уходит провайдеру с заменами чувствительных данных, ключ провайдера остаётся в Studio. Адрес Cleaner должен быть в списке разрешённых адресов.": "Cleaner gateway for external models: text reaches the provider with sensitive data replaced, and the provider key stays in Studio. The Cleaner address must be on the allowlist.",
  "Частные адреса из списка разрешённых считаются внутренними — не добавляйте туда шлюзы в облачные модели.": "Private addresses on the allowlist count as internal. Do not add gateways to cloud models there.",
  "Адрес Cleaner": "Cleaner address",
  "адрес Cleaner, http(s), хост и порт, без пути": "Cleaner address, http(s), host and port, no path",
  "Служебный ключ": "Service key",
  "Cleaner для всех внешних моделей": "Cleaner for all external models",
  "Принудительный режим закрывает подключения моделей Studio: внешние идут только через Cleaner. Веб-инструменты и внешние MCP закрывает флажок ниже; раздел «Open WebUI» не закрывает ни один из них.": "Forced mode covers Studio model connections: external ones go only through Cleaner. Web tools and external MCP are covered by the option below; neither covers the Open WebUI section.",
  "Веб и внешние MCP — только через Cleaner": "Web and external MCP only through Cleaner",
  "«Интернет» и веб-инструменты MCP (пометка «интернет») — только в диалогах через Cleaner; в остальных диалогах и в разделах они недоступны.": "Internet and MCP web tools (marked “internet”) work only in conversations through Cleaner; other conversations and sections do not get them.",
