  "Продолжить иначе": "Continue differently",
  "Отправить после ответа": "Send after response",
  "Отправить уточнение": "Send clarification",
  "Уточнение…": "Clarification…",
  "Жду освобождения сессии в Codex Desktop или другом приложении. Текст и вложения сохранены.": "Waiting for the session in Codex Desktop or another app to become available. Text and attachments are saved.",
  "Сессия занята в Codex Desktop или другом приложении. Дождитесь её освобождения или продолжите копию с той же историей. Копия и исходная сессия смогут работать независимо.": "This session is busy in Codex Desktop or another app. Wait for it to become available or continue a copy with the same history. Both sessions can work independently.",
  "Продолжить копией": "Continue as copy",
  "Дождаться освобождения": "Wait until available",
  "Жду завершения задания в другом окне. Результат появится здесь.": "Waiting for the task in another window to finish. The result will appear here.",
  "Задание выполняется в другом окне или браузере. Можно дождаться результата или перенести управление сюда.": "This task is running in another window or browser. Wait for the result or take control here.",
  "Задание ждёт вашего ответа, а управление — в другом окне или браузере. Перенесите управление сюда, чтобы ответить.": "This task is waiting for your answer, but another window or browser has control. Take control here to answer.",
  "Задание ждёт вашего ответа, а управление — в другом окне или браузере. Ответьте здесь: если то окно сейчас закрыто, управление перейдёт сюда.": "This task is waiting for your answer, but another window or browser has control. Answer here: if that window is closed now, control moves here.",
  "Связь прервалась — проверяю, принято ли задание…": "Connection lost. Checking whether the task was accepted…",
  "Связь прервалась. Задание возвращено в поле — повторная отправка не запустит его второй раз": "Connection lost. The task is back in the input field. Resending will not start it twice",
  "Связь прервалась": "Connection lost",
