  "{0} ч {1} мин": "{0} h {1} min",
  "Время хода — от принятия задания мостом до конца ответа, вместе с ожиданием ответов на карточки. Скорость — выходные токены хода, делённые на его время.": "Turn time runs from when the bridge accepts the task to the end of the answer, including time spent waiting for replies to cards. Speed is the turn's output tokens divided by its time.",
  "Контекст — текущая заполненность окна. Расход токенов — накопленный за сессию, включая повторное чтение контекста. Данные сообщает помощник.": "Context shows current window usage. Token usage accumulates over the session, including repeated context reads. Data is reported by the assistant.",
  "Из кэша": "Read from cache",
  "Запись в кэш": "Written to cache",
  "Кэш: оценка оставшегося времени": "Cache: estimated time remaining",
  "Таймер кэша — оценка 30 минут от последней обработки контекста современной моделью Codex. Сервер не сообщает точное время хранения и не гарантирует попадание в кэш. Открытие чата отсчёт не продлевает.": "The cache timer estimates 30 minutes from the last context processing by a current Codex model. The server does not report the exact retention time or guarantee a cache hit. Opening the chat does not extend it.",
  "Таймер кэша — оценка по отчёту Claude: 5 минут или час, при смешанных сроках — короткий. Если срок или время обработки неизвестны, показано «—». Открытие чата отсчёт не продлевает.": "The cache timer uses Claude's reported duration: 5 minutes or one hour, taking the shorter duration when mixed. If the duration or processing time is unknown, “—” is shown. Opening the chat does not extend it.",
  "Кэш: время не сообщается. Сведения о кэше": "Cache: time not reported. Cache details",
  "Кэш: ориентировочно осталось {0} мин {1} с": "Cache: approximately {0} min {1} s remaining",
  "Кэш: расчётные {0} минут прошли; состояние серверного кэша неизвестно": "Cache: estimated {0} minutes elapsed; server cache state unknown",
