  "Касание — клик в этой точке, движение — перетаскивание. ПКМ — правый клик. Два пальца прокручивают пульт.": "Tap to click, move to drag. Right click uses the right mouse button. Use two fingers to scroll the controls.",
  "Экран как тачпад: двигайте палец, касайтесь для клика. «Тянуть» удерживает ЛКМ; ↥ ↧ прокручивают компьютер. Два пальца прокручивают пульт.": "Use the screen as a touchpad: move your finger and tap to click. Drag holds the left button; ↥ ↧ scroll the computer. Use two fingers to scroll the controls.",
