  "не менять ({0})": "keep unchanged ({0})",
  "ключ API": "API key",
  "Cleaner: только чат и перевод через сервер. Нужен ключ Cleaner с доступом к подключению и моделям; адрес должен разрешить администратор.": "Cleaner: chat and translation through the server only. Requires a Cleaner key with connection and model access. The address must be allowed by an administrator.",
  "s06: чат и перевод Qwen, расшифровка WhisperX, сканы PaddleOCR и голосовой ввод. Озвучки и координат текста для перевода снимка у этого шлюза нет.": "s06: Qwen chat and translation, WhisperX transcription, PaddleOCR scans and voice input. This gateway does not support speech synthesis or text coordinates for photo translation.",
  "Вид": "View",
  "Адреса из списка администратора студия зовёт сама, остальные — ваш браузер. Фото, видео и речь — только через студию.": "Studio connects to addresses allowed by the administrator. Your browser handles the rest. Photos, video and speech go through Studio only.",
  "Токен": "Token",
  "Добавить во все разделы этого шлюза": "Add to every section this gateway supports",
  "Подключение": "Connection",
  "Новое подключение": "New connection",
