  "Очистить выделение": "Clear selection",
  "Размер кисти": "Brush size",
  "Закрасьте нужную часть фото пальцем или мышью. Пиксели вне выделения будут взяты из исходника без изменений.": "Paint over the area with your finger or mouse. Pixels outside the selection will be preserved from the original.",
