  "Модель: {0} (выбрана в разделе)": "Model: {0} (selected in section)",
  "по умолчанию раздела": "section default",
  "Внешний сервис меняет фото по инструкции. Правка кистью — только через шлюз srvllm.": "An external service edits the photo according to your instructions. Brush edits require the srvllm gateway.",
  "Модель раздела": "Section model",
  "{0} перерисовывает фото. Меньшая сила лучше сохраняет исходник. Для сохранения окружения выделите область кистью.": "{0} redraws the photo. Lower strength preserves more of the original. To keep the surroundings, select an area with the brush.",
  "{0} использует исходное фото и инструкцию. Без выделения области соседние детали тоже могут измениться.": "{0} uses the original photo and instructions. Without a selected area, nearby details may also change.",
