  "Текущий пароль": "Current password",
  "Коды входа включены": "Sign-in codes enabled",
  "Коды входа выключены": "Sign-in codes disabled",
  "Электронная почта": "Email address",
  "Изменить почту": "Change email",
  "Коды входа по умолчанию выключены. При включении после пароля потребуется код из письма.": "Sign-in codes are off by default. When enabled, you will need an emailed code after entering your password.",
  "Письмо о входе с нового устройства": "Email me about sign-ins from a new device",
  "Если вход идёт с устройства, браузера или адреса, которых не было за полгода, на почту придёт письмо: время, устройство, браузер и адрес, без ссылок.": "If someone signs in from a device, browser or address not seen in the last six months, you get an email with the time, device, browser and address, without links.",
  "QR-код для приложения-аутентификатора": "QR code for the authenticator app",
  "Приложение отключено": "Authenticator app turned off",
  "Приложение подключено. Резервных кодов осталось: {0}.": "Authenticator app is set up. Backup codes left: {0}.",
  "Подключить приложение": "Set up the app",
  "Ключ сервера сменился, и приложение больше не действует. Подключите его заново.": "The server key has changed and the app no longer works. Set it up again.",
  "Код из приложения": "Code from the app",
  "QR-код не загрузился — введите ключ вручную.": "The QR code did not load. Enter the key manually.",
  "Отсканируйте QR-код в приложении-аутентификаторе (например, Google Authenticator, Microsoft Authenticator, 2FAS) и введите шестизначный код из него.": "Scan the QR code with an authenticator app (for example, Google Authenticator, Microsoft Authenticator or 2FAS) and enter the six-digit code it shows.",
  "Ключ для ручного ввода:": "Key for manual entry:",
  "Резервные коды": "Backup codes",
  "Сохраните коды в надёжном месте: каждый подходит для входа один раз, если телефона нет под рукой. Больше они не покажутся.": "Keep these codes in a safe place: each one signs you in once when your phone is not at hand. They will not be shown again.",
  "Приложение подключено": "Authenticator app set up",
  "Второй шаг входа и привязки компьютера — код из приложения на телефоне вместо письма: вход не зависит от почты. Если телефон потерян, войдите резервным кодом; без него приложение снимает только оператор сервера.": "The second step of signing in and linking a computer is a code from the app on your phone instead of an email, so signing in does not depend on email. If you lose your phone, sign in with a backup code; without one, only the server operator can remove the app.",
