  "Настройки ntfy сохранены на этом устройстве": "ntfy settings saved on this device",
  "Сервер и тема — с прошлой настройки на этом устройстве. Токен, если он нужен, введите заново и сохраните.": "Server and topic are from this device's previous settings. Enter the token again if needed, then save.",
  "Уведомление отправлено в ntfy — проверьте телефон": "Notification sent to ntfy. Check your phone",
  "Настройки ntfy сброшены": "ntfy settings reset",
  "О чём уведомлять": "What to notify about",
  "Для push и ntfy этого устройства: телефон и компьютер настраиваются отдельно. После выхода из учётки — заново.": "For push and ntfy on this device: set up your phone and computer separately. Set up again after signing out.",
  "Вопросы и подтверждения агентов и чата": "Agent and chat questions and confirmations",
  "Конец хода агентов и ответы чата": "Agent turn ends and chat answers",
  "Готовность заданий разделов": "Finished section tasks",
  "Служебные: копия базы, отключённая ссылка, неверный код входа": "Service: database backup, disabled link, wrong sign-in code",
  "Не беспокоить": "Do not disturb",
  "С": "From",
  "По": "To",
  "Тихие часы — по часовому поясу учётки: {0}. В них не приходит ничего; о ждущем вопросе агента или чата после них напомнит повтор, если напоминание включено.": "Quiet hours follow the account time zone: {0}. Nothing arrives during them; if reminders are on, a reminder about a waiting agent or chat question comes after they end.",
  "Напомнить о ждущем вопросе агента или чата": "Remind about a waiting agent or chat question",
  "Не напоминать": "Do not remind",
  "Через 10 минут": "After 10 minutes",
  "Через 30 минут": "After 30 minutes",
  "Через час": "After an hour",
  "Повтор приходит, если вопрос или подтверждение не закрыты и чат не открыт, — не больше трёх раз.": "A reminder comes if the question or confirmation is still open and the chat is not open, up to three times.",
  "Укажите начало и конец тихих часов — разное время": "Set different start and end times for quiet hours",
  "Выбор уведомлений сохранён на этом устройстве": "Notification choice saved on this device",
  "Уведомления агентов и готовности заданий без Google-сервисов. Включается отдельно на каждом устройстве, по умолчанию выключено. После выхода из учётки включите заново.": "Agent and task completion notifications without Google services. Enable separately on each device; off by default. Enable again after signing out.",
  "Уведомления через ntfy на этом устройстве": "ntfy notifications on this device",
  "Сервер ntfy": "ntfy server",
  "Токен доступа": "Access token",
  "Для каждого устройства используйте отдельную тему: ntfy доставляет сообщение всем её подписчикам. Сохраните настройки, подпишитесь на тему в приложении ntfy на этом устройстве и разрешите ему работу в фоне.": "Use a separate topic for each device: ntfy delivers messages to every subscriber. Save the settings, subscribe in the ntfy app on this device and allow it to run in the background.",
  "Токен хранится зашифрованным. Сервер ntfy получает только уведомление и ссылку, без переписки. «Проверить» отправляет уведомление с сохранёнными настройками.": "The token is encrypted. The ntfy server receives only notifications and links, without conversations. Check sends a notification using the saved settings.",
