  "Только без локальных изменений копии и удалений — иначе пометка у копии и уведомление.": "Only when the copy has no local changes and nothing is deleted; otherwise the copy is marked and you get a notification.",
  "Изменения будут уходить в копии после каждого хода.": "Changes will be sent to the copies after every turn.",
  "Отправка после хода выключена.": "Sending after turns is off.",
  "Зеркала проектов": "Project mirrors",
  "Все копии проектов на компьютерах этой учётной записи. Отправка после хода переносит изменения сама, только если в копии нет своих изменений и ничего не удаляется.": "All project copies on this account's computers. Sending after a turn transfers changes automatically only when the copy has no local changes and nothing is deleted.",
