  "проекта больше нет": "project no longer exists",
  "Отправлять после хода": "Send after turns",
  "После успешного хода в этом проекте отправлять изменения в остальные копии": "After a successful turn in this project, send changes to the other copies",
  "Отвязать": "Unlink",
  "Отвязать копию?": "Unlink copy?",
  "Снимается только настройка зеркала: папка и файлы останутся на компьютере. Если в группе останется одна копия, зеркало исчезнет целиком.": "Only the mirror setting is removed: the folder and files stay on the computer. If a single copy remains in the group, the whole mirror is removed.",
