  "Обновите мост на компьютере исходного проекта.": "Update the bridge on the source computer.",
  "Участник видит все чаты и файлы этого проекта, может менять файлы и запускать агентов. Агенты работают с правами и подключениями владельца компьютера.": "Members can see all chats and files in this project, edit files and run agents. Agents use the computer owner's permissions and connections.",
