  "Термины и имена переводятся одинаково во всех кусках документа. Модель получает только пары, которые встретились в переводимом куске, — через Cleaner вместе с текстом и его очисткой.": "Terms and names are translated the same way in every chunk of a document. The model receives only the pairs found in the chunk being translated; through Cleaner they are cleaned together with the text.",
