  "Порядок кнопок нового чата. Для автоматического создания чата выбирается первый доступный агент. Сохраняется для всех ваших устройств.": "Order of new chat buttons. Automatic chat creation uses the first available agent. Saved across all your devices.",
  "Claude Code, Codex, OpenCode и DeepSeek Harness": "Claude Code, Codex, OpenCode and DeepSeek Harness",
  "Модель, усилие и права для новых чатов на всех ваших устройствах. Начатые чаты сохраняют свой выбор. Показаны текущие настройки подключённого компьютера; в проекте они уточняются при открытии чата.": "Model, effort and permissions for new chats across all your devices. Existing chats keep their choices. Shows the connected computer's current settings, refined when opening a project chat.",
