  "Всего": "Total",
  " Контекстов Cleaner в очереди удаления: {0}.": " Cleaner contexts queued for deletion: {0}.",
  " Отложено после неудачи ({0}): {1}.": " Deferred after failure ({0}): {1}.",
  "Счёт — по записям истории, без миниатюр. Тексты чатов и промпты — в базе: удалённое из неё остаётся в копиях базы, пока его не вытеснят 7 новых копий (обычно неделю).": "Counts are based on history records, excluding thumbnails. Chat texts and prompts are in the database. Deleted data remains in backups until replaced by 7 new backups, usually one week.",
  "Ключ задан": "Key set",
  "Ключа нет": "No key",
  "Кнопка «Интернет» в чате — поиск и чтение страниц через Exa по вашему ключу и субтитры YouTube — включается только с ключом; убранный ключ выключает её во всех диалогах. Ключ — на ": "The Internet button in chat enables Exa search, page reading and YouTube subtitles with your key. Removing the key disables it in every conversation. Get a key at ",
  ": бесплатно $10 в месяц, без привязанной карты перерасхода нет. Поисковые запросы и адреса страниц видит Exa.": ": $10 free per month, no overage without a linked card. Exa sees search queries and page addresses.",
