  "Не нужно": "No thanks",
  "Сервер вернул некорректные данные подписки push — обновите страницу": "Server returned invalid push subscription data. Refresh the page",
  "Push на этом устройстве": "Push on this device",
  "Приходят и при закрытой студии и погасшем экране: запрос разрешения, вопрос и конец хода Claude Code, Codex, OpenCode или DeepSeek Harness, готовность и ошибки фоновых заданий. Идут через службу браузера (Apple, Google или Mozilla) — содержимое зашифровано, но факт и время им видны. На iPhone — только у студии, добавленной на экран «Домой».": "Notifications arrive even when Studio is closed or the screen is off: permission requests, questions, completed turns in Claude Code, Codex, OpenCode or DeepSeek Harness, and background task results or errors. Delivered through Apple, Google or Mozilla; contents are encrypted, but timing is visible. On iPhone, add Studio to the Home Screen first.",
  "Уведомления выключены на этом устройстве": "Notifications disabled on this device",
  "Уведомления включены на этом устройстве": "Notifications enabled on this device",
