  "Уведомления": "Notifications",
  "Сообщать о готовности, когда студия открыта в фоне": "Notify when ready while Studio is in the background",
  "Только на этом устройстве и пока студия открыта — свёрнутая вкладка или окно. При включённом push готовность сообщает сервер, без повторного локального уведомления. Промптов, текстов и имён файлов в уведомлении нет.": "Only on this device while Studio is open in a background tab or window. With push enabled, the server sends completion notifications without duplicate local notifications. Prompts, texts and filenames are excluded.",
  "привязан": "linked",
  "отозван": "revoked",
  "связь потеряна": "disconnected",
  "открыт": "unlocked",
  "открыт PIN": "unlocked with PIN",
  "неверный PIN": "incorrect PIN",
  "новый чат": "new chat",
  "Отозвать компьютер?": "Revoke computer?",
  "Мост на нём отключится и не войдёт снова без нового входа. История подключений останется.": "Its bridge will disconnect and require a new sign-in. Connection history is kept.",
  "Заменить компьютер: {0}": "Replace computer: {0}",
  "Заменить компьютер?": "Replace computer?",
  "«{0}» получит ключ выбранного компьютера: id, имя, доступы участников, зеркала и вкладки останутся, а мост на прежнем компьютере отключится.": "“{0}” will take over the key of the selected computer. Its ID, name, member access, mirrors and tabs are kept, and the bridge on the old computer will disconnect.",
  "Строка нового компьютера уйдёт без возврата вместе с его вкладками, отметками чатов, выданными на нём доступами участников, его копиями зеркал и ссылками «Поделиться» на его чаты. У зеркал прежнего компьютера выключится отправка после хода, а первая сверка покажет различия как локальные изменения. Соответствия чатов перенесите командами моста export-chats и import-chats.": "The new computer's own entry is removed for good together with its tabs, chat marks, the project access granted on it, its mirror copies and the Share links to its chats. The former computer's mirrors stop sending after each turn, and the first comparison shows differences as local changes. Move chat mappings with the bridge commands export-chats and import-chats.",
  "С выбранным компьютером пропадут: доступов участникам — {0}, копий зеркал — {1}, ссылок «Поделиться» — {2}.": "Removed with the selected computer: project access grants — {0}, mirror copies — {1}, Share links — {2}.",
  "Новый компьютер": "New computer",
  "выберите новый компьютер": "choose the new computer",
  "Покинуть": "Leave",
  "Покинуть совместные проекты?": "Leave shared projects?",
  "Проекты этого компьютера пропадут из «Агентов», ваши вкладки в них закроются. Вернуть доступ может только владелец компьютера.": "This computer's projects will disappear from Agents and your tabs in them will close. Only the computer owner can give access back.",
  "Компьютеры (Claude Code, Codex, OpenCode и DeepSeek Harness)": "Computers (Claude Code, Codex, OpenCode and DeepSeek Harness)",
  "История подключений": "Connection history",
  "Важное": "Important",
  "Всё": "All",
  "Какие события показать": "Events to show",
  "обрывов связи: {0}": "disconnections: {0}",
  "Удалятся безвозвратно: вся история разделов {0} вместе с файлами, образцы голосов, все ссылки ": "This will permanently delete all history and files in {0}, voice samples, all shared ",
  "«Поделиться», личные базы знаний с документами (и из корзины), а в разделе «{0}» — вкладки, отметки чатов и непрочитанные завершения. Сами чаты Claude Code, ": "links, personal knowledge bases with their documents (including those in the trash), and tabs, chat marks and unread completions in “{0}”. Claude Code, ",
  "Codex, OpenCode и DeepSeek Harness хранятся на компьютерах и останутся.": "Codex, OpenCode and DeepSeek Harness chats are stored on computers and will remain.",
  "Удалить всю историю": "Delete all history",
  "Подключения, пресеты и ключи останутся, как и настройки, компьютеры, выданные доступы к проектам и журнал безопасности.": "Connections, presets, keys, settings, computers, granted project access and the security log are kept.",
  "Да, удалить навсегда": "Yes, delete permanently",
  "Удалить всю историю?": "Delete all history?",
  "Точно? Отменить удаление нельзя.": "Are you sure? Deletion cannot be undone.",
  "История удалена, но файлов на хранилище ещё {0}: удалятся, когда оно станет доступно": "History deleted, but {0} files remain in storage. They will be deleted when it becomes available",
