  "Личные подключения и модели по умолчанию для чата и перевода.": "Personal connections and default models for chat and translation.",
  "Как подключить и использовать": "How to connect and use",
  "В Cleaner откройте «Ключи» и создайте ключ с доступом к облачному подключению и его моделям. У каждого пользователя должна быть своя учётная запись Cleaner. Адрес сервиса разрешает администратор Studio.": "Open Keys in Cleaner and create a key with access to a cloud connection and its models. Each user needs their own Cleaner account. The service address must be allowed by a Studio administrator.",
  "«Проверить» проверяет связь и доступ к моделям. Перед отправкой из чата вы увидите очищенный текст; в переводе очистка выполняется автоматически. Настройки по умолчанию действуют для новых диалогов и переводов. Адрес и ключ можно изменить через меню «⋯» подключения.": "Check tests connectivity and model access. Chat shows cleaned text before sending; translation cleans automatically. Defaults apply to new conversations and translations. Edit the address and key from the connection's More menu.",
