  "Нужны Claude Code, Codex, OpenCode или DeepSeek Harness. Для Windows и Linux нужен Python 3.11+, для Linux также venv. Установщик macOS 13+ включает Python.": "Requires Claude Code, Codex, OpenCode or DeepSeek Harness. Windows and Linux require Python 3.11+. Linux also requires venv. The macOS 13+ installer includes Python.",
  "В Windows и macOS откройте установщик и вставьте этот адрес в поле «Адрес студии». В Linux получите команду и выполните её в терминале в течение 10 минут.": "On Windows and macOS, open the installer and paste this address into the Studio address field. On Linux, run the provided command in a terminal within 10 minutes.",
