  "Добавить навыки по умолчанию": "Add default skills",
  "Навык — готовое задание, которое вызывается через «/» в поле ввода: его текст уходит в сообщение, а то, что вы допишете, — уточнением. Навыки с отметкой «Кнопкой в пустом чате» показываются в новом чате «{0}» до первого сообщения.": "A skill is a ready-made task you call with “/” in the message field: its text goes into the message, and whatever you add becomes the clarification. Skills marked “As a button in an empty chat” appear in a new {0} chat before the first message.",
  "Навыки по умолчанию": "Default skills",
  "Новые учётки получают навыки своего языка при первом открытии навыков; «Добавить навыки по умолчанию» в настройках возвращает недостающие. Уже созданные навыки пользователей правка не меняет.": "New accounts get the skills of their language the first time their skills are opened; “Add default skills” in settings brings back missing ones. Editing does not change skills users already have.",
